'use strict';

// MODULES //

import isnan from '@stdlib/math-base-assert-is-nan';
import incrcv from '@stdlib/stats-incr-cv';


// MAIN //

/**
* Returns an accumulator function which incrementally computes the coefficient of variation (CV), ignoring `NaN` values.
*
* @param {number} [mean] - mean value
* @throws {TypeError} must provide a number
* @returns {Function} accumulator function
*
* @example
* var accumulator = incrnancv();
*
* var cv = accumulator();
* // returns null
*
* cv = accumulator( 2.0 );
* // returns 0.0
*
* cv = accumulator( NaN );
* // returns 0.0
*
* cv = accumulator( 1.0 );
* // returns ~0.47
*
* cv = accumulator();
* // returns ~0.47
*
* @example
* var accumulator = incrnancv( 3.0 );
*/
function incrnancv( mean ) {
	var cv;
	if ( arguments.length ) {
		cv = incrcv( mean );
	} else {
		cv = incrcv();
	}
	return accumulator;

	/**
	* If provided a value, the accumulator function returns an updated coefficient of variation. If not provided a value, the accumulator function returns the current coefficient of variation.
	*
	* @private
	* @param {number} [x] - new value
	* @returns {(number|null)} coefficient of variation or null
	*/
	function accumulator( x ) {
		if ( arguments.length === 0 ) {
			return cv();
		}
		if ( isnan( x ) ) {
			return cv();
		}
		return cv( x );
	}
}


// EXPORTS //

export default incrnancv;
